    '① แท็บถาม-ตอบ: เลือกสาขา ช่วงวันที่ (กรุงเทพ) และประเภทคำถาม แล้วสร้างคำตอบ AI\n② จากแผนแนะนำ ไปต่อที่ร่างงานติดตามหรือร่างประกาศ\n③ แท็บร่างการดำเนินการ: สร้างคำขออนุมัติ ผู้จัดการอนุมัติและรันจากรอดำเนินการ\n④ แท็บร่าง AI: ตรวจร่างประกาศ/งานและเชื่อมกับประกาศหรือบันทึกงาน\n⑤ โหลดคำถามก่อนหน้าจากบทสนทนาล่าสุด\n⑥ หลังอนุมัติ ใช้เปิดขั้นตอนถัดไปเพื่อ prefill ประกาศ/บันทึกงาน',
