  adminFinancialStatements: 'บัญชีบริหาร',
  helpSum_admin_financial_statements:
    'บัญชีบริหารสำหรับดูผลประกอบการร้านครับ ยอดไม่ต้องเท่าบัญชีภาษี ดูงบกำไรขาดทุน งบดุล และมาร์จิ้นตามสาขาและช่วงเวลา งบดุลมีเงินกู้ยืม (2150) และเงินให้กู้ (1150) เงินเดือน (5310) ลงในเดือนเงินเดือน ไม่ใช่วันจ่าย จ่ายค่า Royalty · GP ที่อนุมัติแล้วลงเป็นค่าใช้จ่ายสาขาและยอดขายสำนักงานใหญ่ตามสลับ VAT รวม/ไม่รวม มุมมอง VAT รวมเท่านั้นที่ใส่ยอดนำส่ง ภ.พ.30 เป็นค่าใช้จ่ายในเดือนภาษี',
  helpHow_admin_financial_statements:
    '① เลือกสาขา เดือนเริ่ม–สิ้นสุด แล้วกดค้นหาครับ เปลี่ยนเดือนหรือสาขาอย่างเดียวจะไม่โหลดใหม่จนกว่าจะกดค้นหาอีกครั้ง ทั้งกำไรขาดทุน งบดุล กระทบยอด และมาร์จิ้นครับ\n② สลับ VAT รวม/ไม่รวม แล้ว ยอดขาย การซื้อ สินค้าคงเหลือ และบิลแฟรนไชส์ที่อนุมัติจะขยับตามกัน ยอดเงินแสดงทศนิยม 2 ตำแหน่ง (0.01 บาท) มุมมองรวมเท่านั้นที่ใส่ยอดนำส่ง ภ.พ.30 เป็นค่าใช้จ่ายในเดือนภาษี ไม่ใช่วันที่โอนธนาคาร\n③ Royalty / GP เดลิเวอรี / Grab GP เข้างบเมื่อ PO บัญชีเป็น Approved แล้วเท่านั้น Draft และค่าธรรมเนียมแพลตฟอร์ม 5528 คนละรายการ\n④ ยอดขายมือและสินค้าคงเหลือต้นงวด บันทึกได้เมื่อเลือกเดือนเดียว มุมมองหลายเดือนใช้ค่าที่บันทึกของแต่ละเดือน\n⑤ เงื่อนไขค้นหาและผลลัพธ์ยังอยู่เมื่อสลับเมนูหรือแท็บย่อย\n⑥ เงินเดือนเข้างบของเดือนเงินเดือน ไม่ใช่วันจ่าย ถ้ามีเงินเดือนที่ยืนยันแล้ว ระบบไม่นับถอนธนาคารหรือเงินสดย่อยที่เหมือนเงินเดือนซ้ำ',
