  accCompPnd3EmptyStoreHint:
    'ไม่พบรายการที่ตรงชื่อสาขา — ลองค้นหาแบบสาขาทั้งหมด และตรวจว่าแถวบัญชีมี store_name ว่างหรือต่างชื่อหรือไม่',
