  accCompRdFilingWorkflowNote:
    '※ e-Filing รับเฉพาะไฟล์ .rdx เท่านั้น ไม่สามารถอัปโหลด .txt ได้\n① ดาวน์โหลด TXT จาก ERP → ② เปิดโปรแกรม RD Prep นำเข้าแล้วบันทึกเป็น .rdx → ③ อัปโหลด .rdx ที่ efiling.rd.go.th',
