    'สรุปเพื่ออ้างอิงเท่านั้น ภาระและกำหนดจริงขึ้นกับกฎหมาย ประกาศกรมสรรพากร/DBD รอบบัญชี และประเภทธุรกิจ — ควรยืนยันกับที่ปรึกษาบัญชี',
  accCompSched_sec1_title: '1. ภาษีมูลค่าเพิ่ม — ภ.พ.30',
  accCompSched_sec1_body:
    'ยื่นบ่อยที่สุด\n\n✔ ยื่นแบบและชำระ: โดยหลักภายในวันที่ 15 ของเดือนถัดไป (ยื่นอิเล็กทรอนิกส์มักขยายได้เล็กน้อย)\n\nตัวอย่าง: รอบภาษีเดือนมี.ค. → ประมาณ 15 เม.ย. (หรือ ~23 เม.ย. หากมีการขยาย)',
  accCompSched_sec2_title: '2. ภาษีหัก ณ ที่จ่าย — ภ.ง.ด.',
  accCompSched_sec2_body:
    'เงินเดือน ค่าจ้าง ค่าบริการ ฯลฯ ที่มีการหัก ณ ที่จ่าย\n\n✔ ยื่นแบบและชำระ: โดยหลักภายในวันที่ 7 ของเดือนถัดไป (ยื่นอิเล็กทรอนิกส์มักขยายได้)\n\nตัวอย่าง: จ่ายเดือนมี.ค. → ประมาณ 7 เม.ย. (หรือ ~15 เม.ย.)',
  accCompSched_sec3_title: '3. ภ.ง.ด. 51 — ภาษีเงินได้นิติบุคคลกลางปี',
  accCompSched_sec3_body:
    'คำนวณ/ยื่นระหว่างรอบบัญชี\n\n✔ ยื่น: ภายใน 2 เดือนนับจากครบ 6 เดือนนับจากวันเริ่มรอบบัญชี (แล้วแต่รอบบัญชี)\n\nตัวอย่าง: รอบ ม.ค.–ธ.ค. → มักสิ้นเดือน มิ.ย.',
  accCompSched_sec4_title: '4. ภ.ง.ด. 50 — ภาษีเงินได้นิติบุคคลประจำปี',
  accCompSched_sec4_body:
    'หลังปิดบัญชี\n\n✔ ยื่นและชำระ: ภายใน 150 วันนับจากวันสิ้นรอบบัญชี\n\nตัวอย่าง: สิ้นรอบ 31 ธ.ค. → ประมาณสิ้นเดือน พ.ค. ปีถัดไป',
  accCompSched_sec5_title: '5. ยื่นงบการเงิน — กรมพัฒนาธุรกิจการค้า (DBD)',
  accCompSched_sec5_body:
    'ยื่นงบประจำปีต่อ DBD\n\n✔ กำหนดส่ง: ภายใน 5 เดือนนับจากสิ้นรอบบัญชี\n\nตัวอย่าง: สิ้นรอบ 31 ธ.ค. → มักสิ้นเดือน พ.ค. ปีถัดไป (อาจใกล้เคียง ภ.ง.ด. 50)',
  accCompSched_sec6_title: '6. ประชุมใหญ่สามัญผู้ถือหุ้น (AGM)',
  accCompSched_sec6_body:
    'ตามกฎหมายบริษัท\n\n✔ จัดประชุม: ภายใน 4 เดือนนับจากสิ้นรอบบัญชี\n\nตัวอย่าง: สิ้นรอบ 31 ธ.ค. → ประมาณสิ้นเดือน เม.ย. ปีถัดไป',
